async function main() {
    console.log("🚀 Starting Fresh Seeding (EXTENDED 10-PAGE EDITION)...");

    // 1. Clear ALL existing data
    console.log("🧹 Clearing existing data...");
    await db.delete(userQuestsTable);
    await db.delete(questsTable);
    await db.delete(readingProgressTable);
    await db.delete(storyPinsTable);
    await db.delete(storyPageFavoritesTable);
    await db.delete(storyPagesTable);
    await db.delete(storiesTable);
    await db.delete(categoriesTable);
    await db.delete(heroesTable);
    await db.delete(sessionTable);
    await db.delete(accountTable);
    await db.delete(verificationTable);
    await db.delete(userTable);

    // 2. Insert categories
    const [fabelCat, legendaCat, dongengCat] = await db.insert(categoriesTable).values([
        { name: "Fabel", description: "Cerita tentang hewan yang berperilaku seperti manusia." },
        { name: "Legenda", description: "Cerita rakyat yang dianggap benar-benar terjadi." },
        { name: "Dongeng", description: "Cerita khayalan atau fantasi yang penuh keajaiban." },
    ]).returning();

    // 3. Insert Quests
    await db.insert(questsTable).values([
        { title: "Pembaca Kilat", description: "Selesaikan 2 bab hari ini", xpReward: 50, type: "READING", targetValue: 2, isDaily: true },
        { title: "Pakar Kata", description: "Pelajari 5 kosa kata baru", xpReward: 30, type: "VOCABULARY", targetValue: 5, isDaily: true }
    ]);

    const categoryMap: Record<string, number> = {
        "Fabel": fabelCat.id,
        "Legenda": legendaCat.id,
        "Dongeng": dongengCat.id
    };

    // 4. Seeding Logic with 10-page enforcement
    for (const story of STORIES_DATA) {
        const [insertedStory] = await db.insert(storiesTable).values({
            title: story.title,
            slug: story.slug,
            preview: story.preview,
            content: story.content, 
            categoryId: categoryMap[story.category],
            thumbnailUrl: story.thumbnail,
            status: "published"
        }).returning();

        const paragraphs = story.content.split("\n\n");
        
        // Loop to create exactly 10 pages
        for (let p = 0; p < 10; p++) {
            // Take 2 paragraphs per page
            const startIndex = p * 2;
            const pageContent = paragraphs.slice(startIndex, startIndex + 2).join("\n\n") 
                || (p === 9 ? "Pelajaran berharga dari kisah ini adalah kebaikan akan selalu menang." : "Halaman ini sedang dalam pemeliharaan konten...");

            await db.insert(storyPagesTable).values({
                storyId: insertedStory.id,
                pageNumber: p + 1,
                content: pageContent,
                imageUrl: story.thumbnail
            });
        }
        console.log(`✅ Fully Seeded (10 Pages + AI Thumbnail): ${story.title}`);
    }

    console.log("✨ Seeding completed successfully!");
    process.exit(0);
}

main().catch((err) => {
    console.error("❌ Seeding failed:", err);
    process.exit(1);
});
